using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class FinalizeExactGroundCollision
{
 static Mesh Skin(Mesh source,string path,Vector3 extrusion){var positions=source.vertices;var t=source.triangles;var vertices=positions.ToList();var both=t.ToList();var ids=new int[positions.Length];var weld=new Dictionary<Vector3Int,int>();var edges=new Dictionary<(int,int),(int,int,int)>();for(int i=0;i<positions.Length;i++){var key=Vector3Int.RoundToInt(positions[i]*1000);if(!weld.TryGetValue(key,out int id)){id=weld.Count;weld[key]=id;}ids[i]=id;}for(int i=0;i<t.Length;i+=3){both.AddRange(new[]{t[i],t[i+2],t[i+1]});for(int j=0;j<3;j++){int a=t[i+j],b=t[i+(j+1)%3],ia=ids[a],ib=ids[b];var key=ia<ib?(ia,ib):(ib,ia);if(edges.TryGetValue(key,out var edge))edges[key]=(edge.Item1,edge.Item2,edge.Item3+1);else edges[key]=(a,b,1);}}foreach(var edge in edges.Values){if(edge.Item3!=1)continue;var a=positions[edge.Item1];var b=positions[edge.Item2];int n=vertices.Count;vertices.AddRange(new[]{a,b,a+extrusion,b+extrusion});both.AddRange(new[]{n,n+1,n+2,n+1,n+3,n+2,n+2,n+1,n,n+2,n+3,n+1});}var mesh=new Mesh{name=source.name+" solid collision",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.SetTriangles(both,0);mesh.RecalculateBounds();var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing==null){AssetDatabase.CreateAsset(mesh,path);return mesh;}EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(existing);return existing;}
 public static string Main(){if(Application.isPlaying)throw new Exception("Stop Play");string folder="Assets/Game/Generated/MatchedForestCollision";var forest=GameObject.Find("Forest - imported dirt road environment");int skin=0,removed=0;
 foreach(var patch in forest.GetComponentsInChildren<ForestGroundPatch>()){var f=patch.GetComponent<MeshFilter>();var c=patch.GetComponent<MeshCollider>();c.sharedMesh=Skin(f.sharedMesh,folder+"/Exact visible skin "+patch.name+".asset",f.transform.InverseTransformVector(Vector3.down*100));c.enabled=true;PrefabUtility.RecordPrefabInstancePropertyModifications(c);skin++;}
 var shell=GameObject.Find("Forest solid collision - visible surface");foreach(var c in shell.GetComponentsInChildren<MeshCollider>()){if(!c.enabled)continue;var original=c.sharedMesh;var v=original.vertices;var t=original.triangles;var keep=new List<int>();for(int i=0;i<t.Length;i+=3){var a=c.transform.TransformPoint(v[t[i]]);var b=c.transform.TransformPoint(v[t[i+1]]);var d=c.transform.TransformPoint(v[t[i+2]]);if(Mathf.Abs(Vector3.Cross(b-a,d-a).y)>.00001f){removed++;continue;}keep.AddRange(new[]{t[i],t[i+1],t[i+2]});}if(keep.Count==t.Length)continue;if(keep.Count==0){c.enabled=false;continue;}var mesh=UnityEngine.Object.Instantiate(original);mesh.SetTriangles(keep,0);mesh.RecalculateBounds();string path=folder+"/Closed boundary "+c.name+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing==null)AssetDatabase.CreateAsset(mesh,path);else{EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;EditorUtility.SetDirty(existing);}c.sharedMesh=mesh;}
 var route=UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>();foreach(var arm in route.arms)foreach(var prefab in arm.modules){string path=AssetDatabase.GetAssetPath(prefab);var contents=PrefabUtility.LoadPrefabContents(path);try{foreach(var patch in contents.GetComponentsInChildren<ForestGroundPatch>()){var f=patch.GetComponent<MeshFilter>();var c=patch.GetComponent<MeshCollider>();c.sharedMesh=Skin(f.sharedMesh,"Assets/Game/Generated/AuthoredLongForest/Solid "+prefab.name+" "+f.name+".asset",f.transform.InverseTransformVector(Vector3.down*100));skin++;}PrefabUtility.SaveAsPrefabAsset(contents,path);}finally{PrefabUtility.UnloadPrefabContents(contents);}}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());return "Exact two-sided visible mesh collision on "+skin+" original/module ground pieces; removed "+removed+" interpolated support triangles; only closed boundary walls retained below the exact visible skin. Render geometry unchanged.";
 }
}
